use clap::{Command, Arg, value_parser, ArgAction};
use std::net::{SocketAddr, IpAddr};

fn parse_byte_size(s: &str) -> Result<u64, String> {
    if s.is_empty() { return Err("invalid digit found in string".to_string()); }
    let last = s.chars().last().unwrap();
    if last == 'k' || last == 'M' || last == 'G' || last == 'T' {
        let num_str = &s[..s.len()-1];
        if num_str.is_empty() { return Err("invalid digit found in string".to_string()); }
        let n: u64 = num_str.parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
        let factor = match last {
            'k' => 1024u64,
            'M' => 1024*1024,
            'G' => 1024*1024*1024,
            'T' => 1024*1024*1024*1024,
            _ => 1,
        };
        n.checked_mul(factor).ok_or_else(|| "number too large to fit in target type".to_string())
    } else if last.is_ascii_alphabetic() {
        Err("invalid digit found in string".to_string())
    } else {
        s.parse::<u64>().map_err(|e| e.to_string())
    }
}

fn build_cmd() -> Command {
    Command::new("executable")
        .subcommand(
            Command::new("server")
                .about("Run as a perf server")
                .arg(Arg::new("listen").long("listen").value_name("LISTEN").default_value("[::]:4433").help("Address to listen on").value_parser(value_parser!(SocketAddr)))
                .arg(Arg::new("key").short('k').long("key").value_name("KEY").help("TLS private key in DER format").value_parser(value_parser!(std::path::PathBuf)))
                .arg(Arg::new("cert").short('c').long("cert").value_name("CERT").help("TLS certificate in PEM format").value_parser(value_parser!(std::path::PathBuf)))
                .arg(Arg::new("send-buffer-size").long("send-buffer-size").value_name("SEND_BUFFER_SIZE").default_value("2M").help("Send buffer size in bytes\n\nThis can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.").value_parser(parse_byte_size))
                .arg(Arg::new("recv-buffer-size").long("recv-buffer-size").value_name("RECV_BUFFER_SIZE").default_value("2M").help("Receive buffer size in bytes\n\nThis can use SI suffixes for sizes. For example, 1M will request 1MiB, 10G will request 10GiB.").value_parser(parse_byte_size))
                .arg(Arg::new("conn-stats").long("conn-stats").help("Whether to print connection statistics").action(ArgAction::SetTrue))
