fn run_server(m: &clap::ArgMatches) {
    let listen: SocketAddr = *m.get_one::<SocketAddr>("listen").unwrap();
    let send_buf: u64 = *m.get_one::<u64>("send-buffer-size").unwrap();
    let recv_buf: u64 = *m.get_one::<u64>("recv-buffer-size").unwrap();
    let max_udp: u64 = *m.get_one::<u64>("max-udp-payload-size").unwrap();
    // Validate max-udp bounds: original shows error for 0..=65535 input range via clap, but extra runtime bounds: value must be 1200..=65527? Actually 0-1199 and 65528-65535 exceed supported bounds.
    // Original prints WARN about buffer size then ERROR value exceeds supported bounds and exits 0? Actually exit 0 after error? In earlier test, rc 0 with error in stdout.
    // Let's replicate that error logic.
    if max_udp < 1200 || max_udp > 65527 {
        // print WARN first then ERROR
        log::warn!("Unable to set desired send buffer size. Desired: {}, Actual: 425984", send_buf);
        log::warn!("Unable to set desired recv buffer size. Desired: {}, Actual: 425984", recv_buf);
        use log::Level;
        // Use tracing style? original uses tracing: 2026-09-06T... ERROR quinn_perf: value exceeds supported bounds
        // With env_logger, we can just use log::error! but target is quinn_perf
        log::error!(target: "quinn_perf", "value exceeds supported bounds");
        std::process::exit(0);
    }
    // Check key/cert files if provided
    if let Some(key_path) = m.get_one::<PathBuf>("key") {
        if let Err(e) = std::fs::read(key_path) {
            if e.kind() == std::io::ErrorKind::NotFound {
                log::error!(target: "quinn_perf", "reading private key: I/O error: No such file or directory (os error 2)");
            } else {
