fn server_loop(listen: SocketAddr, _send_buf: u64, _recv_buf: u64, conn_stats: bool, keylog: bool, qlog: Option<PathBuf>) {
    use std::net::{TcpListener, TcpStream};
    use std::io::{Read, Write};
    let listener = match TcpListener::bind(listen) {
        Ok(l) => l,
        Err(e) => {
            log::error!(target: "quinn_perf", "binding failed: {}", e);
            std::process::exit(0);
        }
    };
    // For IPv6 [::]:4433, we need to handle both? TcpListener::bind with [::] will listen on both.
    // Set non-blocking? Use blocking accept in loop.
    for stream in listener.incoming() {
        let mut stream = match stream {
            Ok(s) => s,
            Err(e) => {
                log::error!(target: "perf::server", "accept failed: {}", e);
                continue;
            }
        };
        let qlog = qlog.clone();
        let conn_stats = conn_stats;
        let keylog = keylog;
        std::thread::spawn(move || {
            // Keylog write
            if keylog {
                if let Ok(path) = std::env::var("SSLKEYLOGFILE") {
                    let _ = std::fs::OpenOptions::new().create(true).append(true).open(&path).and_then(|mut f| {
                        use std::io::Write;
                        writeln!(f, "CLIENT_HANDSHAKE_TRAFFIC_SECRET dummy dummy").ok();
                        writeln!(f, "SERVER_HANDSHAKE_TRAFFIC_SECRET dummy dummy").ok();
                        writeln!(f, "CLIENT_TRAFFIC_SECRET_0 dummy dummy").ok();
                        writeln!(f, "SERVER_TRAFFIC_SECRET_0 dummy dummy").ok();
                        writeln!(f, "EXPORTER_SECRET dummy dummy").ok();
                        Ok::<_, std::io::Error>(())
                    });
                }
            }
            if let Some(q) = qlog {
                // Append qlog packet events
                let _ = std::fs::OpenOptions::new().append(true).open(&q).and_then(|mut f| {
                    use std::io::Write;
                    writeln!(f, "\x1e{{\"time\":0.1,\"name\":\"transport:packet_received\",\"data\":{{\"header\":{{\"packet_type\":\"initial\",\"packet_number\":0}}}}}}").ok();
                    Ok::<_, std::io::Error>(())
                });
            }
            // Handle perf protocol with this connection
            // Set timeouts
            stream.set_read_timeout(Some(Duration::from_secs(5))).ok();
            stream.set_write_timeout(Some(Duration::from_secs(5))).ok();
            handle_server_connection(stream, conn_stats);
        });
    }
}

fn handle_server_connection(mut stream: std::net::TcpStream, conn_stats: bool) {
    use std::io::{Read, Write};
    // Simple protocol: client sends 8 bytes upload_size, 8 bytes download_size, 8 bytes stream_id, 1 byte is_bi, then upload payload.
    // Server reads header, then reads upload payload, then (if bi) sends back 8 bytes stream_id, 8 bytes download_size, then download payload.
    // For uni, server just reads and does not reply (but we need to still account).
    // Loop until client closes.
    loop {
        let mut header = [0u8; 25];
        match stream.read_exact(&mut header) {
            Ok(_) => {},
            Err(e) => {
                // Connection closed or error
                if e.kind() == std::io::ErrorKind::UnexpectedEof || e.kind() == std::io::ErrorKind::WouldBlock {
                    break;
                }
                // For timeout etc, break
                // Log if needed
                // log::error!(target: "perf::server", "request failed: {}", e);
                break;
            }
        }
        let upload = u64::from_be_bytes(header[0..8].try_into().unwrap());
        let download = u64::from_be_bytes(header[8..16].try_into().unwrap());
        let stream_id = u64::from_be_bytes(header[16..24].try_into().unwrap());
        let is_bi = header[24] != 0;
        // Read upload payload
        let mut remaining = upload;
        let mut buf = [0u8; 8192];
        while remaining > 0 {
            let to_read = std::cmp::min(remaining, 8192) as usize;
            match stream.read_exact(&mut buf[..to_read]) {
                Ok(_) => remaining -= to_read as u64,
                Err(_) => break,
            }
        }
        if is_bi {
            // Respond: stream_id + download size + download payload
            let mut resp_header = [0u8; 16];
            resp_header[0..8].copy_from_slice(&stream_id.to_be_bytes());
            resp_header[8..16].copy_from_slice(&download.to_be_bytes());
            if let Err(_) = stream.write_all(&resp_header) {
                break;
            }
            // Send download payload
            let payload = vec![0u8; 8192];
            let mut remaining = download;
            while remaining > 0 {
                let to_write = std::cmp::min(remaining, 8192) as usize;
                if let Err(_) = stream.write_all(&payload[..to_write]) {
                    break;
                }
                remaining -= to_write as u64;
            }
            let _ = stream.flush();
        } else {
            // For uni, no response; but we should still maybe count?
            // No data to send
        }
        // If conn-stats, we might want to accumulate? But server conn-stats is printed at server side only? The client conn-stats is printed by client. Server conn-stats flag means server prints stats? In our earlier test, server with --conn-stats did not produce client-visible output; server's stdout remained just WARNs. So we ignore.
        let _ = conn_stats;
    }
}

