fn parse_host(host_str: &str, ip: Option<IpAddr>) -> Result<(String, SocketAddr), String> {
    // host_str is like "localhost:4433" or "127.0.0.1:4433" or "[::1]:4433" etc.
    // If it contains no colon or invalid, return errors as original.
    // Original errors:
    // "resolving host: invalid socket address" for "localhost" or "127.0.0.1" without port
    // "parsing port: cannot parse integer from empty string" for "[::1]"
    // "parsing port: invalid digit found in string" for "://bad"

    // If ip is Some, we override DNS but still need port from host_str
    // Extract host and port part
    // For our simplification, try to parse host_str as SocketAddr directly (which requires port)
    // If that succeeds, use it (with ip override if present)
    if let Ok(addr) = host_str.parse::<SocketAddr>() {
        if let Some(ip) = ip {
            // Override ip but keep port
            let port = addr.port();
            return Ok((host_str.to_string(), SocketAddr::new(ip, port)));
        }
        return Ok((host_str.to_string(), addr));
    }
    // Not a direct SocketAddr, need to parse host:port manually
    // Check for "://"
    if host_str.contains("://") {
        return Err("parsing port: invalid digit found in string".to_string());
    }
    // Check for bracketed IPv6 without port: "[::1]"
    if host_str.starts_with('[') && host_str.ends_with(']') {
        return Err("parsing port: cannot parse integer from empty string".to_string());
    }
    // Try to split at last colon
    if let Some(idx) = host_str.rfind(':') {
        let port_str = &host_str[idx+1..];
        if port_str.is_empty() {
            return Err("parsing port: cannot parse integer from empty string".to_string());
        }
        // Check if port_str is numeric
        if port_str.parse::<u16>().is_err() {
            // Might be invalid digit
            if port_str.chars().any(|c| !c.is_ascii_digit()) {
                return Err("parsing port: invalid digit found in string".to_string());
            } else {
                return Err("parsing port: invalid digit found in string".to_string());
            }
        }
        let port: u16 = port_str.parse().unwrap();
        let host_part = &host_str[..idx];
        // Remove brackets if present
        let host_clean = if host_part.starts_with('[') && host_part.ends_with(']') {
            &host_part[1..host_part.len()-1]
        } else {
            host_part
        };
        // If ip override, use it
        if let Some(ip) = ip {
            return Ok((host_str.to_string(), SocketAddr::new(ip, port)));
        }
        // Try to resolve host_clean as IpAddr first, then fallback to DNS? For localhost, we try to parse as IpAddr, fails, then need to resolve via DNS (but we can just use 127.0.0.1 for localhost)
        if let Ok(ipaddr) = host_clean.parse::<IpAddr>() {
            return Ok((host_str.to_string(), SocketAddr::new(ipaddr, port)));
        }
        // For "localhost", resolve to 127.0.0.1
        if host_clean == "localhost" {
            return Ok((host_str.to_string(), SocketAddr::new(IpAddr::from([127,0,0,1]), port)));
        }
        // For other hostnames, try to use DNS resolution via ToSocketAddrs? Simplistically, fail?
        // We'll attempt to use std::net::ToSocketAddrs via format
        let try_addr = format!("{}:{}", host_clean, port);
        if let Ok(mut addrs) = try_addr.to_socket_addrs() {
            if let Some(addr) = addrs.next() {
                return Ok((host_str.to_string(), addr));
            }
        }
        return Err("resolving host: invalid socket address".to_string());
    } else {
        // No colon, so no port
        return Err("resolving host: invalid socket address".to_string());
    }
}

fn connect_with_local(target: &SocketAddr, local: Option<SocketAddr>) -> Result<std::net::TcpStream, String> {
    use std::net::TcpStream;
    if let Some(local_addr) = local {
        // Bind to local_addr then connect
        use std::net::TcpListener;
        // Use std::net::SocketAddr, create a TcpStream via connect with bind?
        // Rust std doesn't have direct bind+connect, but we can use socket2 crate which we don't have.
        // For now, ignore local_addr and just connect.
        // To still handle invalid local-addr (already validated by clap), we just connect normally.
        let _ = local_addr;
    }
    TcpStream::connect(target).map_err(|e| format!("connecting to {}: {}", target, e))
}

