    let matches = cmd.try_get_matches().unwrap_or_else(|e| e.exit());
    match matches.subcommand() {
        Some(("server", sub)) => run_server(sub),
        Some(("client", sub)) => run_client(sub),
        _ => unreachable!(),
    }
}

