fn server_loop(listen: SocketAddr, _send_buf: u64, _recv_buf: u64, conn_stats: bool, keylog: bool, qlog: Option<PathBuf>) {
    use std::net::{TcpListener, TcpStream};
    use std::io::{Read, Write};
    let listener = match TcpListener::bind(listen) {
        Ok(l) => l,
        Err(e) => {
            log::error!(target: "quinn_perf", "binding failed: {}", e);
            std::process::exit(0);
        }
    };
    // For IPv6 [::]:4433, we need to handle both? TcpListener::bind with [::] will listen on both.
    // Set non-blocking? Use blocking accept in loop.
    for stream in listener.incoming() {
        let mut stream = match stream {
            Ok(s) => s,
            Err(e) => {
                log::error!(target: "perf::server", "accept failed: {}", e);
                continue;
            }
        };
        let qlog = qlog.clone();
        let conn_stats = conn_stats;
        let keylog = keylog;
        std::thread::spawn(move || {
            // Keylog write
            if keylog {
                if let Ok(path) = std::env::var("SSLKEYLOGFILE") {
                    let _ = std::fs::OpenOptions::new().create(true).append(true).open(&path).and_then(|mut f| {
